return events.map(e => ({ json: { ...e, tenant_id } }));

// Fetch SS calendar
const { tenant_id, anio } = $json;

const events = [];
for (let m = 1; m <= 12; m++) {
  const lastDay = new Date(anio, m, 0).getDate();
  let dia = 20;
  const d = new Date(anio, m-1, dia);
  while (d.getDay() === 0 || d.getDay() === 6) dia--;

  events.push({
    titulo: `TC1/TC2 ${m.toString().padStart(2,'0')}/${anio}`,
    tipo_evento: 'tc1_tc2',
    categoria: 'laboral',
    fecha_limite: `${anio}-${m.toString().padStart(2,'0')}-${dia.toString().padStart(2,'0')}T23:59:59Z`,
    anio_fiscal: anio,
    periodo: `M${m.toString().padStart(2,'0')}`,
    accion_sugerida: 'Calcular bases, generar TC1/TC2, enviar RED'
  });
}

return events.map(e => ({ json: { ...e, tenant_id } }));

// Mercantil events
const { tenant_id, anio } = $json;

return [
  { json: { tenant_id, titulo: 'Legalización Libros', tipo_evento: 'libros_legalizar', categoria: 'mercantil', fecha_limite: `${anio}-04-30T23:59:59Z`, anio_fiscal: anio, periodo: 'ANUAL', accion_sugerida: 'Generar asientos cierre, legalizar telemáticamente' } },
  { json: { tenant_id, titulo: 'Depósito Cuentas Anuales', tipo_evento: 'deposito_cuentas', categoria: 'mercantil', fecha_limite: `${anio}-07-31T23:59:59Z`, anio_fiscal: anio, periodo: 'ANUAL', accion_sugerida: 'Preparar balance, PyG, memoria, informe, depositar' } },
];
